using SagaOrderWorkflow;using Xunit;public sealed class SagaTests{[Fact]public void Happy_path_completes(){var s=new OrderSaga(Guid.NewGuid());s.Handle(Guid.NewGuid(),"PaymentCaptured");s.Handle(Guid.NewGuid(),"InventoryReserved");Assert.Equal(SagaStatus.Completed,s.Status);}[Fact]public void Inventory_failure_requests_compensation(){var s=new OrderSaga(Guid.NewGuid());s.Handle(Guid.NewGuid(),"PaymentCaptured");s.Handle(Guid.NewGuid(),"InventoryRejected");Assert.Equal("RefundPayment",Assert.Single(s.Commands,x=>x.Type=="RefundPayment").Type);}[Fact]public void Duplicate_message_is_ignored(){var s=new OrderSaga(Guid.NewGuid());var id=Guid.NewGuid();Assert.True(s.Handle(id,"PaymentCaptured"));Assert.False(s.Handle(id,"PaymentCaptured"));}[Fact]public void Invalid_transition_fails(){Assert.Throws<InvalidOperationException>(()=>new OrderSaga(Guid.NewGuid()).Handle(Guid.NewGuid(),"InventoryReserved"));}}
